  .hud-bottom-left { left: calc(12px + var(--safe-l)); bottom: calc(14px + var(--safe-b)); }
  .slot-list { display: none; }
  .med-bag { padding: 6px 8px; }
  .med-icon { width: 18px; height: 18px; font-size: 13px; }
  .med-bag b { font-size: 13px; }
  .med-bag small { font-size: 6px; }
  .weapon-card { right: calc(12px + var(--safe-r)); bottom: calc(14px + var(--safe-b)); width: 168px; padding: 8px 10px 7px; }
  .weapon-title b { font-size: 18px; }
  .weapon-title span, .fire-mode { font-size: 6px; }
  .ammo-row b { font-size: 26px; }
  .weapon-spec { display: none; }
  .interact-prompt { bottom: auto; top: 52%; }
  .toast { top: 22%; font-size: 9px; }
  .crosshair { transform: translate(-50%, -50%) scale(.82); }
  .scope-reticle { width: 82vw; height: 82vw; }
  .scope-mask { background: radial-gradient(circle at 50% 50%, transparent 0 41vw, rgba(0,0,0,.985) calc(41vw + 1px)); }
  .pause-card { padding: 26px 22px; }
  .setting-row { grid-template-columns: 1fr 110px 48px; gap: 10px; padding: 12px 0; }
  .setting-row b { font-size: 12px; }
  .setting-row small { font-size: 8px; }
  .settings-card header { padding: 20px 20px 14px; }
  .settings-card h2 { font-size: 30px; }
  .settings-body { padding: 6px 20px 14px; }
  .settings-card footer { padding: 0 20px 20px; }
  .end-card { padding: 32px 20px 24px; }
  .end-rank { top: 18px; right: 20px; font-size: 36px; }
  .end-card h2 { font-size: 56px; }
  .end-stats { grid-template-columns: repeat(2, 1fr); }
  .end-stats div:nth-child(2) { border-right: 0; }
  .end-stats div:nth-child(-n+2) { border-bottom: 1px solid var(--line); }
  .end-actions { flex-direction: column; }
  .end-actions .btn { width: 100%; }
}

@media (max-height: 560px) and (orientation: landscape) {
  .lobby-main { padding-top: 0; }
  .hero-copy h1 { font-size: 54px; }
  .hero-sub { display: none; }
  .drop-preview { display: none; }
